-- L&T Finance (CLI customer 77ddd7f3-bd79-4453-b0d7-f7e533687353) billing rate reconciliation
-- against the client cost sheet "Billing for Un-Armed Guard For 12 Hours Per Day".
-- One rate per state; Admin Charges and Service Charge split as separate employer lines;
-- billing divisor set to a fixed 27 days so the daily rate matches (e.g. Gujarat 28026.11/27 = 1038.00).
begin;

insert into billing_day_bases (code, name, description, method, fixed_days, is_default, enabled, sort_order)
select 'FIXED_27', 'Fixed 27 Days', 'Billing is divided by a fixed 27 days per month (client-agreed divisor).', 'fixed_days', 27, false, true, 6
 where not exists (select 1 from billing_day_bases where code = 'FIXED_27');

